'use strict';
const NS_SCRIPT_ENDPOINT = 'https://script.google.com/macros/s/AKfycbzRHK2n1D0WjWw4NxcwtH7FQb7eRsZxVagFnYtiz5quAFec2BLfwgJ26C0OG6FTKcPB/exec';
let nsPublicIPCache = null;
async function fetchPublicIP() {
  if (nsPublicIPCache) return nsPublicIPCache;
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 3000);
    const res = await fetch('https://api.ipify.org?format=json', { signal: controller.signal });
    clearTimeout(timer);
    if (res.ok) {
      const data = await res.json();
      if (data && data.ip) {
        nsPublicIPCache = data.ip;
        return nsPublicIPCache;
      }
    }
  } catch (e) {
    try {
      const res2 = await fetch('https://api64.ipify.org?format=json');
      if (res2.ok) {
        const data2 = await res2.json();
        if (data2 && data2.ip) {
          nsPublicIPCache = data2.ip;
          return nsPublicIPCache;
        }
      }
    } catch (err) {}
  }
  return nsPublicIPCache || 'Unknown';
}
if (typeof window !== 'undefined') {
  window.addEventListener('DOMContentLoaded', () => { fetchPublicIP(); });
}
function detectBrowser() {
  const ua = navigator.userAgent;
  if (ua.includes('Firefox/')) return 'Firefox';
  if (ua.includes('SamsungBrowser/')) return 'Samsung Internet';
  if (ua.includes('Opera') || ua.includes('OPR/')) return 'Opera';
  if (ua.includes('Edg/')) return 'Microsoft Edge';
  if (ua.includes('Chrome/')) return 'Chrome';
  if (ua.includes('Safari/')) return 'Safari';
  return 'Browser';
}
function detectOS() {
  const ua = navigator.userAgent;
  if (ua.includes('Win')) return 'Windows';
  if (ua.includes('Mac')) return 'macOS';
  if (ua.includes('Android')) return 'Android';
  if (ua.includes('Linux')) return 'Linux';
  if (ua.includes('iPhone') || ua.includes('iPad') || ua.includes('iPod')) return 'iOS';
  return 'Unknown OS';
}
function detectDevice() {
  const ua = navigator.userAgent;
  if (/(tablet|ipad|playbook|silk)|(android(?!.*mobi))/i.test(ua)) return 'Tablet';
  if (/Mobile|iP(hone|od)|Android|BlackBerry|IEMobile|Kindle|Silk-Accelerated|(hpw|web)OS|Opera M(obi|ini)/i.test(ua)) return 'Mobile';
  return 'Desktop';
}
function detectScreenResolution() {
  return `${window.screen.width}x${window.screen.height}`;
}
function detectTimezone() {
  try {
    return Intl.DateTimeFormat().resolvedOptions().timeZone || 'Asia/Kolkata';
  } catch (e) {
    return 'Asia/Kolkata';
  }
}
function getUTMParams() {
  const params = new URLSearchParams(window.location.search);
  return {
    utmSource: params.get('utm_source') || '',
    utmMedium: params.get('utm_medium') || '',
    utmCampaign: params.get('utm_campaign') || '',
    utmContent: params.get('utm_content') || '',
    utmTerm: params.get('utm_term') || ''
  };
}
function injectToastStyles() {
  if (document.getElementById('ns-toast-styles')) return;
  const style = document.createElement('style');
  style.id = 'ns-toast-styles';
  style.textContent = `
    .ns-toast-container {
      position: fixed;
      top: 24px;
      right: 24px;
      z-index: 999999;
      display: flex;
      flex-direction: column;
      gap: 12px;
      max-width: 420px;
      width: calc(100vw - 48px);
      pointer-events: none;
    }
    .ns-toast {
      pointer-events: auto;
      background: rgba(1, 23, 49, 0.96);
      backdrop-filter: blur(16px);
      -webkit-backdrop-filter: blur(16px);
      border: 1px solid rgba(5, 153, 168, 0.4);
      box-shadow: 0 16px 36px rgba(1, 23, 49, 0.4);
      border-radius: 16px;
      padding: 18px 22px;
      color: #ffffff;
      transform: translateX(120%);
      opacity: 0;
      transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1), opacity 0.4s ease;
    }
    .ns-toast.visible {
      transform: translateX(0);
      opacity: 1;
    }
    .ns-toast-success {
      border-left: 5px solid #75d766;
    }
    .ns-toast-error {
      border-left: 5px solid #ef4444;
      border-color: rgba(239, 68, 68, 0.4);
    }
    .ns-toast-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 12px;
      margin-bottom: 8px;
    }
    .ns-toast-title {
      font-weight: 700;
      font-size: 1.05rem;
      color: #ffffff;
      display: flex;
      align-items: center;
      gap: 6px;
    }
    .ns-toast-close {
      color: rgba(255, 255, 255, 0.6);
      font-size: 1.2rem;
      line-height: 1;
      padding: 4px;
      cursor: pointer;
      background: none;
      border: none;
      transition: color 0.2s ease;
    }
    .ns-toast-close:hover {
      color: #ffffff;
    }
    .ns-toast-body {
      font-size: 0.925rem;
      color: rgba(255, 255, 255, 0.88);
      line-height: 1.55;
    }
    .btn-spinner {
      display: inline-block;
      width: 16px;
      height: 16px;
      border: 2px solid rgba(255, 255, 255, 0.35);
      border-top-color: #ffffff;
      border-radius: 50%;
      animation: ns-spin 0.8s linear infinite;
      vertical-align: middle;
      margin-right: 6px;
    }
    @keyframes ns-spin {
      to { transform: rotate(360deg); }
    }
  `;
  document.head.appendChild(style);
}
function showToastNotification({ title, message, type = 'success' }) {
  injectToastStyles();
  let toastContainer = document.getElementById('ns-toast-container');
  if (!toastContainer) {
    toastContainer = document.createElement('div');
    toastContainer.id = 'ns-toast-container';
    toastContainer.className = 'ns-toast-container';
    document.body.appendChild(toastContainer);
  }
  const toast = document.createElement('div');
  toast.className = `ns-toast ns-toast-${type}`;
  const isSuccess = type === 'success';
  toast.innerHTML = `
    <div class="ns-toast-content">
      <div class="ns-toast-header">
        <span class="ns-toast-title">${title}</span>
        <button type="button" class="ns-toast-close" aria-label="Close">✕</button>
      </div>
      <div class="ns-toast-body">${message.replace(/\n/g, '<br/>')}</div>
    </div>
  `;
  toastContainer.appendChild(toast);
  requestAnimationFrame(() => {
    toast.classList.add('visible');
  });
  const removeToast = () => {
    toast.classList.remove('visible');
    setTimeout(() => {
      if (toast.parentNode) toast.parentNode.removeChild(toast);
    }, 400);
  };
  toast.querySelector('.ns-toast-close')?.addEventListener('click', removeToast);
  setTimeout(removeToast, isSuccess ? 6500 : 5000);
}
async function submitNovaForm({
  form,
  submitBtn,
  data = {},
  loadingText = 'Booking...',
  onSuccessCallback = null
}) {
  if (!form || !submitBtn) return false;
  if (form.dataset.submitting === 'true' || submitBtn.disabled) return false;
  if (!form.querySelector('input[name="website"]')) {
    const hpInput = document.createElement('input');
    hpInput.type = 'text';
    hpInput.name = 'website';
    hpInput.tabIndex = -1;
    hpInput.autocomplete = 'off';
    hpInput.setAttribute('aria-hidden', 'true');
    hpInput.style.cssText = 'display:none !important; opacity:0; position:absolute; left:-9999px; width:0; height:0; z-index:-1;';
    form.appendChild(hpInput);
  }
  form.dataset.submitting = 'true';
  submitBtn.disabled = true;
  const originalHtml = submitBtn.innerHTML;
  submitBtn.innerHTML = `<span class="btn-spinner"></span> ${loadingText}`;
  try {
    const publicIP = await fetchPublicIP();
    const utm = getUTMParams();
    const honeypotValue = (form.querySelector('input[name="website"]')?.value || data.website || '').trim();
    const payload = {
      name: data.name || '',
      mobile: data.mobile || '',
      email: data.email || '',
      course: data.course || '',
      city: data.city || '',
      message: data.message || '',
      website: honeypotValue,
      pageUrl: window.location.href,
      referrer: document.referrer || '',
      utmSource: utm.utmSource,
      utmMedium: utm.utmMedium,
      utmCampaign: utm.utmCampaign,
      utmContent: utm.utmContent,
      utmTerm: utm.utmTerm,
      browser: detectBrowser(),
      device: detectDevice(),
      os: detectOS(),
      screenResolution: detectScreenResolution(),
      timezone: detectTimezone(),
      "public IP": publicIP,
      publicIP: publicIP,
      ip: publicIP
    };
    const res = await fetch(NS_SCRIPT_ENDPOINT, {
      method: 'POST',
      headers: { 'Content-Type': 'text/plain;charset=utf-8' },
      body: JSON.stringify(payload)
    });
    let isSuccess = res.ok;
    let responseMsg = '';
    try {
      const json = await res.json();
      if (json) {
        if (json.success === false) {
          isSuccess = false;
          responseMsg = json.message || '';
        } else if (json.message) {
          responseMsg = json.message;
        }
      }
    } catch (e) {
    }
    if (!isSuccess) {
      throw new Error(responseMsg || 'Submission failed');
    }
    form.reset();
    submitBtn.innerHTML = originalHtml;
    submitBtn.disabled = false;
    delete form.dataset.submitting;
    showToastNotification({
      title: '✅ Consultation Booked Successfully!',
      message: 'Thank you for contacting Nova Skills.\n\nOur career counsellor will call you within 2 hours.\n\nPlease keep your phone available.',
      type: 'success'
    });
    if (onSuccessCallback) {
      onSuccessCallback();
    }
    return true;
  } catch (err) {
    console.error('Submission error:', err);
    submitBtn.innerHTML = originalHtml;
    submitBtn.disabled = false;
    delete form.dataset.submitting;
    const errorMsg = err.message && err.message !== 'Submission failed'
      ? err.message
      : 'Something went wrong. Please try again.';
    showToastNotification({
      title: err.message && err.message.includes('Spam') ? 'Spam Detected' : 'Submission Failed',
      message: errorMsg,
      type: 'error'
    });
    return false;
  }
}
window.submitNovaForm = submitNovaForm;
window.showToastNotification = showToastNotification;
function getCurrentPage() {
  const path = window.location.pathname.toLowerCase();
  if (path.endsWith('courses.html') || path.includes('/courses')) return 'courses';
  if (path.endsWith('placements.html') || path.includes('/placements')) return 'placements';
  if (path.endsWith('success-stories.html') || path.includes('/success-stories')) return 'success-stories';
  if (path.endsWith('assessment.html') || path.includes('/assessment')) return 'assessment';
  if (path.endsWith('blog.html') || path.includes('/blog')) return 'blog';
  if (path.endsWith('contact.html') || path.includes('/contact')) return 'contact';
  if (path.includes('/privacy-policy')) return 'privacy-policy';
  if (path.includes('/refund-policy')) return 'refund-policy';
  if (path.includes('/terms-and-conditions')) return 'terms-and-conditions';
  if (path.endsWith('course-detail.html')) return 'courses';
  if (path.endsWith('blog-detail.html')) return 'blog';
  return 'home';
}
