function injectComponents() {
  const page = getCurrentPage();
  const headerSlot = document.getElementById('ns-header');
  if (headerSlot) headerSlot.outerHTML = buildHeaderHTML(page);
  const footerSlot = document.getElementById('ns-footer');
  if (footerSlot) footerSlot.outerHTML = buildFooterHTML();
  document.body.insertAdjacentHTML('beforeend', buildWhatsAppHTML());
  document.body.insertAdjacentHTML('beforeend', buildPopupHTML());
  document.body.insertAdjacentHTML('afterbegin', buildScrollProgressHTML());
  if (!document.getElementById('nova-ai-widget-script')) {
    const loadAiWidget = () => {
      if (document.getElementById('nova-ai-widget-script')) return;
      const aiScript = document.createElement('script');
      aiScript.id = 'nova-ai-widget-script';
      aiScript.src = '/js/nova-ai-widget.min.js';
      aiScript.defer = true;
      document.body.appendChild(aiScript);
      window.removeEventListener('scroll', loadAiWidget);
      window.removeEventListener('mousemove', loadAiWidget);
      window.removeEventListener('touchstart', loadAiWidget);
    };
    if ('requestIdleCallback' in window) {
      requestIdleCallback(() => setTimeout(loadAiWidget, 3500));
    } else {
      setTimeout(loadAiWidget, 3500);
    }
    window.addEventListener('scroll', loadAiWidget, { passive: true });
    window.addEventListener('mousemove', loadAiWidget, { passive: true });
    window.addEventListener('touchstart', loadAiWidget, { passive: true });
  }
}
function initShared() {
  initScrollProgress();
  initNavBehaviour();
  initAnnouncementBar();
  initConsultationPopup();
  initYearAuto();
  initWhatsAppDelay();
}
function initScrollProgress() {
  const bar = document.getElementById('scroll-progress-bar');
  if (!bar) return;
  window.addEventListener('scroll', () => {
    const st = window.scrollY;
    const dh = document.documentElement.scrollHeight - window.innerHeight;
    bar.style.width = dh > 0 ? `${(st / dh) * 100}%` : '0%';
  }, { passive: true });
}
function initNavBehaviour() {
  const header = document.getElementById('main-header');
  const hamburger = document.getElementById('hamburger');
  const navLinks = document.getElementById('nav-links');
  if (!header || !hamburger || !navLinks) return;
  let navOverlay = document.getElementById('nav-overlay');
  if (!navOverlay) {
    navOverlay = document.createElement('div');
    navOverlay.id = 'nav-overlay';
    navOverlay.className = 'nav-overlay';
    document.body.appendChild(navOverlay);
  }
  window.addEventListener('scroll', () => {
    header.classList.toggle('scrolled', window.scrollY > 50);
  }, { passive: true });
  function openMenu() {
    hamburger.classList.add('open');
    hamburger.setAttribute('aria-expanded', 'true');
    navLinks.classList.add('open');
    navOverlay.classList.add('visible');
    document.body.style.overflow = 'hidden';
  }
  function closeMenu() {
    hamburger.classList.remove('open');
    hamburger.setAttribute('aria-expanded', 'false');
    navLinks.classList.remove('open');
    navOverlay.classList.remove('visible');
    document.body.style.overflow = '';
  }
  hamburger.addEventListener('click', (e) => {
    e.stopPropagation();
    if (navLinks.classList.contains('open')) {
      closeMenu();
    } else {
      openMenu();
    }
  });
  navOverlay.addEventListener('click', closeMenu);
  navLinks.querySelectorAll('a').forEach(link => {
    link.addEventListener('click', (e) => {
      if (!link.classList.contains('dropdown-toggle')) {
        closeMenu();
      }
    });
  });
  document.querySelectorAll('.dropdown-toggle').forEach(toggle => {
    toggle.addEventListener('click', (e) => {
      if (window.innerWidth <= 1024) {
        e.preventDefault();
        const dropdown = toggle.closest('.dropdown');
        dropdown.classList.toggle('open');
      }
    });
  });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && navLinks.classList.contains('open')) {
      closeMenu();
    }
  });
}
function initAnnouncementBar() {
  const bar = document.getElementById('announcement-bar');
  const closeBtn = document.getElementById('close-announcement');
  const stage = document.getElementById('announcement-stage');
  const prevBtn = document.getElementById('announcement-prev');
  const nextBtn = document.getElementById('announcement-next');
  const dotsContainer = document.getElementById('announcement-dots');
  if (!bar) return;
  if (localStorage.getItem('ns_announcement_closed') === 'true') {
    bar.style.display = 'none';
    return;
  }
  const slides = bar.querySelectorAll('.announcement-slide');
  const dots = dotsContainer ? dotsContainer.querySelectorAll('.dot') : [];
  const totalSlides = slides.length;
  if (totalSlides === 0) return;
  let currentIndex = parseInt(sessionStorage.getItem('ns_announcement_index') || '0', 10);
  if (isNaN(currentIndex) || currentIndex >= totalSlides) currentIndex = 0;
  let timer = null;
  const ROTATE_INTERVAL = 6000; // 6 seconds
  function showSlide(index, direction = 'next') {
    if (index === currentIndex && slides[index].classList.contains('active')) return;
    slides.forEach((slide, i) => {
      slide.classList.remove('active', 'slide-out');
      if (i === currentIndex) {
        slide.classList.add('slide-out');
      }
    });
    currentIndex = (index + totalSlides) % totalSlides;
    sessionStorage.setItem('ns_announcement_index', currentIndex);
    setTimeout(() => {
      slides[currentIndex].classList.add('active');
    }, 50);
    dots.forEach((dot, i) => {
      dot.classList.toggle('active', i === currentIndex);
    });
  }
  function nextSlide() {
    showSlide(currentIndex + 1, 'next');
  }
  function prevSlide() {
    showSlide(currentIndex - 1, 'prev');
  }
  function startTimer() {
    stopTimer();
    timer = setInterval(nextSlide, ROTATE_INTERVAL);
  }
  function stopTimer() {
    if (timer) clearInterval(timer);
  }
  slides.forEach((s, i) => {
    s.classList.toggle('active', i === currentIndex);
  });
  dots.forEach((d, i) => {
    d.classList.toggle('active', i === currentIndex);
  });
  nextBtn?.addEventListener('click', () => {
    nextSlide();
    startTimer();
  });
  prevBtn?.addEventListener('click', () => {
    prevSlide();
    startTimer();
  });
  dots.forEach(dot => {
    dot.addEventListener('click', (e) => {
      const idx = parseInt(e.target.dataset.slide, 10);
      showSlide(idx);
      startTimer();
    });
  });
  bar.addEventListener('mouseenter', stopTimer);
  bar.addEventListener('mouseleave', startTimer);
  let touchStartX = 0;
  stage?.addEventListener('touchstart', (e) => {
    touchStartX = e.changedTouches[0].screenX;
  }, { passive: true });
  stage?.addEventListener('touchend', (e) => {
    const touchEndX = e.changedTouches[0].screenX;
    const diff = touchStartX - touchEndX;
    if (Math.abs(diff) > 30) {
      if (diff > 0) nextSlide();
      else prevSlide();
      startTimer();
    }
  }, { passive: true });
  closeBtn?.addEventListener('click', () => {
    stopTimer();
    bar.style.transition = 'max-height 0.3s ease, opacity 0.3s ease, padding 0.3s ease';
    bar.style.maxHeight = '0';
    bar.style.opacity = '0';
    bar.style.padding = '0';
    localStorage.setItem('ns_announcement_closed', 'true');
    setTimeout(() => bar.style.display = 'none', 320);
  });
  startTimer();
}
function initYearAuto() {
  document.querySelectorAll('.year-auto').forEach(el => {
    el.textContent = new Date().getFullYear();
  });
}
function initWhatsAppDelay() {
  const btn = document.getElementById('whatsapp-btn');
  if (!btn) return;
  btn.style.opacity = '0'; btn.style.transform = 'scale(0.5) translateY(20px)';
  btn.style.transition = 'all 0.5s cubic-bezier(0.34,1.56,0.64,1)';
  setTimeout(() => { btn.style.opacity = '1'; btn.style.transform = 'scale(1) translateY(0)'; }, 2500);
}
const POPUP_STORAGE_KEY = 'ns_popup_dismissed';
const POPUP_RESHOW_MS = 24 * 60 * 60 * 1000; // 24 hours
function shouldShowPopup() {
  const val = localStorage.getItem(POPUP_STORAGE_KEY);
  if (!val) return true;
  const dismissed = parseInt(val, 10);
  return Date.now() - dismissed > POPUP_RESHOW_MS;
}
function openConsultationPopup() {
  const overlay = document.getElementById('popup-overlay');
  if (!overlay) return;
  document.body.classList.add('modal-open-hide-widgets');
  overlay.removeAttribute('hidden');
  document.body.style.overflow = 'hidden';
  requestAnimationFrame(() => overlay.classList.add('visible'));
  document.getElementById('popup-name')?.focus();
}
function closeConsultationPopup() {
  const overlay = document.getElementById('popup-overlay');
  if (!overlay) return;
  document.body.classList.remove('modal-open-hide-widgets');
  overlay.classList.remove('visible');
  setTimeout(() => {
    overlay.setAttribute('hidden', '');
    document.body.style.overflow = '';
  }, 350);
  localStorage.setItem(POPUP_STORAGE_KEY, String(Date.now()));
  sessionStorage.setItem('consultation_popup_dismissed', 'true');
}
window.openConsultationPopup = openConsultationPopup;
window.closeConsultationPopup = closeConsultationPopup;
function initConsultationPopup() {
  const overlay = document.getElementById('popup-overlay');
  const closeBtn = document.getElementById('popup-close');
  const form = document.getElementById('popup-form');
  if (!overlay) return;
  closeBtn?.addEventListener('click', closeConsultationPopup);
  overlay.addEventListener('click', (e) => {
    if (e.target === overlay) closeConsultationPopup();
  });
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape' && !overlay.hasAttribute('hidden')) closeConsultationPopup();
  });
  form?.addEventListener('submit', (e) => {
    e.preventDefault();
    let valid = true;
    const nameEl = document.getElementById('popup-name');
    const phoneEl = document.getElementById('popup-phone');
    const nameErr = document.getElementById('popup-name-error');
    const phoneErr = document.getElementById('popup-phone-error');
    [nameErr, phoneErr].forEach(el => { if(el) el.textContent = ''; });
    [nameEl, phoneEl].forEach(el => { if(el) el.style.borderColor = ''; });
    if (!nameEl?.value.trim()) {
      if (nameErr) nameErr.textContent = 'Please enter your full name';
      if (nameEl) { nameEl.style.borderColor = 'rgba(239,68,68,0.7)'; nameEl.focus(); }
      valid = false;
    }
    const phone = phoneEl?.value.replace(/\D/g,'') || '';
    if (phone.length < 10) {
      if (phoneErr) phoneErr.textContent = 'Please enter a valid 10-digit number';
      if (phoneEl) { phoneEl.style.borderColor = 'rgba(239,68,68,0.7)'; if(valid) phoneEl.focus(); }
      valid = false;
    }
    if (!valid) return;
    const submitBtn = document.getElementById('popup-submit');
    const emailEl = document.getElementById('popup-email');
    const interestEl = document.getElementById('popup-interest');
    submitNovaForm({
      form,
      submitBtn,
      loadingText: 'Booking...',
      data: {
        name: nameEl?.value.trim() || '',
        mobile: phoneEl?.value.trim() || '',
        email: emailEl?.value.trim() || '',
        course: interestEl?.options[interestEl.selectedIndex]?.text || interestEl?.value || ''
      },
      onSuccessCallback: () => {
        setTimeout(() => {
          closeConsultationPopup();
        }, 1500);
      }
    });
  });
  const sessionShown = sessionStorage.getItem('ns_popup_shown_session');
  if (!sessionShown) {
    setTimeout(() => {
      sessionStorage.setItem('ns_popup_shown_session', 'true');
      const enrollModal = document.getElementById('course-enrollment-modal');
      const isEnrollOpen = enrollModal && !enrollModal.hidden && enrollModal.classList.contains('open');
      const aiPanel = document.querySelector('.nova-ai-panel');
      const isAiOpen = aiPanel && aiPanel.classList.contains('open');
      const isUserTyping = document.activeElement && ['INPUT', 'TEXTAREA', 'SELECT'].includes(document.activeElement.tagName);
      if (!isEnrollOpen && !isAiOpen && !isUserTyping) {
        openConsultationPopup();
      }
    }, 5000);
  }
}
function initScrollReveal(selectors = []) {
  const allSelectors = [
    '.stat-card', '.academy-card', '.course-card', '.testimonial-card',
    '.mentor-card', '.process-step', '.project-card', '.blog-card',
    '.why-feature', '.journey-step', '.faq-item', '.placement-stat',
    ...selectors,
  ];
  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.08, rootMargin: '0px 0px -30px 0px' });
  allSelectors.forEach(sel => {
    document.querySelectorAll(sel).forEach((el, i) => {
      el.dataset.animate = 'true';
      el.style.transitionDelay = `${(i % 5) * 0.07}s`;
      observer.observe(el);
    });
  });
  document.querySelectorAll('.section-header, [data-reveal]').forEach(el => {
    el.style.opacity = '0';
    el.style.transform = 'translateY(28px)';
    el.style.transition = 'opacity 0.65s ease, transform 0.65s ease';
    new IntersectionObserver(([entry]) => {
      if (entry.isIntersecting) {
        el.style.opacity = '1';
        el.style.transform = 'translateY(0)';
      }
    }, { threshold: 0.15 }).observe(el);
  });
}
function initCounters() {
  const cards = document.querySelectorAll('[data-count]');
  const obs = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (!entry.isIntersecting || entry.target.dataset.animated) return;
      entry.target.dataset.animated = 'true';
      const end = parseFloat(entry.target.dataset.count);
      const suffix = entry.target.dataset.suffix || '';
      const el = entry.target.querySelector('.stat-number, .count-el');
      if (!el) return;
      const start = performance.now();
      const dur = 1800;
      function tick(now) {
        const p = Math.min((now - start) / dur, 1);
        const v = end * (1 - Math.pow(1 - p, 3));
        el.textContent = (end % 1 !== 0 ? v.toFixed(1) : Math.floor(v)) + suffix;
        if (p < 1) requestAnimationFrame(tick);
        else el.textContent = end + suffix;
      }
      requestAnimationFrame(tick);
    });
  }, { threshold: 0.3 });
  cards.forEach(c => obs.observe(c));
}
function initFAQAccordion(containerSelector = '.faq-grid') {
  const container = document.querySelector(containerSelector);
  if (!container) return;
  container.querySelectorAll('.faq-item').forEach(item => {
    const btn = item.querySelector('.faq-question');
    const ans = item.querySelector('.faq-answer');
    if (!btn || !ans) return;
    btn.addEventListener('click', () => {
      const isOpen = btn.getAttribute('aria-expanded') === 'true';
      container.querySelectorAll('.faq-question').forEach(b => {
        b.setAttribute('aria-expanded', 'false');
        b.closest('.faq-item')?.querySelector('.faq-answer')?.setAttribute('hidden', '');
      });
      if (!isOpen) {
        btn.setAttribute('aria-expanded', 'true');
        ans.removeAttribute('hidden');
      }
    });
  });
}
function handleNavAuthClick(e) {
  if (e) e.preventDefault();
  const userStr = localStorage.getItem('novaskills_user');
  if (userStr) {
    try {
      const user = JSON.parse(userStr);
      if (user && user.role === 'Admin') {
        window.location.href = 'admin.html';
        return;
      } else {
        window.location.href = 'student.html';
        return;
      }
    } catch (err) {}
  }
  window.location.href = 'login.html';
}
