const COURSE_CATALOG_METADATA = {
  'AI Digital Marketing Professional': { academy: 'Digital Marketing Academy', duration: '3 Months', fee: '₹24,999', category: 'digital-marketing' },
  'AI Mastery Program': { academy: 'AI Academy', duration: '6 Months', fee: '₹39,999', category: 'ai' },
  'Full Stack Programming Foundation': { academy: 'Programming Academy', duration: '6 Months', fee: '₹44,999', category: 'programming' },
  'Creative Design Mastery': { academy: 'Design Academy', duration: '6 Months', fee: '₹39,999', category: 'design' },
  'Motion Graphics Mastery': { academy: 'Video & Motion Academy', duration: '6 Months', fee: '₹39,999', category: 'video' },
  'AI Digital Marketing Mastery': { academy: 'Digital Marketing Academy', duration: '6 Months', fee: '₹44,999', category: 'digital-marketing' }
};
function openEnrollmentModal(courseName, academyName) {
  injectEnrollmentModalHTML();
  const modal = document.getElementById('course-enrollment-modal');
  const titleSpan = document.getElementById('enroll-course-title-span');
  const cardCourseName = document.getElementById('card-course-name');
  const cardAcademyName = document.getElementById('card-academy-name');
  const cardDuration = document.getElementById('card-duration');
  const cardFee = document.getElementById('card-fee');
  const courseInput = document.getElementById('enroll-course-display');
  const academyInput = document.getElementById('enroll-academy-display');
  const categoryInput = document.getElementById('enroll-category-display');
  const durationInput = document.getElementById('enroll-duration-display');
  const feeInput = document.getElementById('enroll-fee-display');
  const errDiv = document.getElementById('enroll-form-error');
  const formContainer = document.getElementById('enroll-form-container');
  const successContainer = document.getElementById('enroll-success-container');
  const meta = COURSE_CATALOG_METADATA[courseName] || {
    academy: academyName || 'Nova Skills Academy',
    duration: '3 to 6 Months',
    fee: '₹24,999',
    category: 'general'
  };
  const finalCourse = courseName || 'Selected Course';
  const finalAcademy = academyName || meta.academy;
  if (titleSpan) titleSpan.textContent = finalCourse;
  if (cardCourseName) cardCourseName.textContent = finalCourse;
  if (cardAcademyName) cardAcademyName.textContent = finalAcademy;
  if (cardDuration) cardDuration.textContent = meta.duration;
  if (cardFee) cardFee.textContent = meta.fee;
  if (courseInput) courseInput.value = finalCourse;
  if (academyInput) academyInput.value = finalAcademy;
  if (categoryInput) categoryInput.value = meta.category;
  if (durationInput) durationInput.value = meta.duration;
  if (feeInput) feeInput.value = meta.fee;
  if (errDiv) errDiv.setAttribute('hidden', '');
  if (formContainer) formContainer.removeAttribute('hidden');
  if (successContainer) successContainer.setAttribute('hidden', '');
  document.body.classList.add('modal-open-hide-widgets');
  if (modal) {
    modal.hidden = false;
    requestAnimationFrame(() => modal.classList.add('open'));
    document.body.style.overflow = 'hidden';
    document.getElementById('enroll-name')?.focus();
  }
}
window.openEnrollmentModal = openEnrollmentModal;
function closeEnrollmentModal() {
  const modal = document.getElementById('course-enrollment-modal');
  document.body.classList.remove('modal-open-hide-widgets');
  if (modal) {
    modal.classList.remove('open');
    setTimeout(() => {
      modal.hidden = true;
      document.body.style.overflow = '';
    }, 300);
  }
}
window.closeEnrollmentModal = closeEnrollmentModal;
async function handleEnrollmentSubmit(e) {
  e.preventDefault();
  const form = document.getElementById('course-enrollment-form');
  const errDiv = document.getElementById('enroll-form-error');
  const formContainer = document.getElementById('enroll-form-container');
  const successContainer = document.getElementById('enroll-success-container');
  const submitBtn = document.getElementById('enroll-submit-btn');
  const courseName = document.getElementById('enroll-course-display')?.value || '';
  const academyName = document.getElementById('enroll-academy-display')?.value || '';
  const category = document.getElementById('enroll-category-display')?.value || '';
  const duration = document.getElementById('enroll-duration-display')?.value || '';
  const fee = document.getElementById('enroll-fee-display')?.value || '';
  const name = document.getElementById('enroll-name')?.value.trim() || '';
  const phone = document.getElementById('enroll-phone')?.value.trim() || '';
  const email = document.getElementById('enroll-email')?.value.trim() || '';
  const city = document.getElementById('enroll-city')?.value.trim() || '';
  const qualification = document.getElementById('enroll-qualification')?.value || 'Graduate';
  const mode = document.getElementById('enroll-mode')?.value || 'Online – Interactive Live with Trainer';
  const batch = document.getElementById('enroll-batch')?.value || 'Upcoming Batch';
  const startDate = document.getElementById('enroll-start-date')?.value || 'Immediate';
  const userMessage = document.getElementById('enroll-message')?.value.trim() || '';
  if (errDiv) errDiv.setAttribute('hidden', '');
  if (!name || name.length < 2) {
    showEnrollError('Please enter your full name.');
    return;
  }
  if (!phone || !/^[6-9]\d{9}$/.test(phone)) {
    showEnrollError('Please enter a valid 10-digit Indian mobile number.');
    return;
  }
  if (!email || !/\S+@\S+\.\S+/.test(email)) {
    showEnrollError('Please enter a valid email address.');
    return;
  }
  if (!city) {
    showEnrollError('Please enter your city.');
    return;
  }
  const fullMessageDetails = [
    `Qualification: ${qualification}`,
    `Preferred Mode: ${mode}`,
    `Preferred Batch: ${batch}`,
    `Start Date: ${startDate}`,
    fee ? `Course Fee: ${fee}` : '',
    duration ? `Duration: ${duration}` : '',
    userMessage ? `User Note: ${userMessage}` : ''
  ].filter(Boolean).join(' | ');
  const courseTitleFull = courseName 
    ? `${courseName}${academyName ? ' (' + academyName + ')' : ''}` 
    : 'Course Enrollment';
  const success = await submitNovaForm({
    form,
    submitBtn,
    loadingText: 'Securing Your Seat... 🔒',
    data: {
      name,
      mobile: phone,
      phone,
      email,
      course: courseTitleFull,
      city,
      message: fullMessageDetails
    },
    onSuccessCallback: () => {
      const leadData = {
        action: 'Student Enrollment Enquiry',
        timestamp: new Date().toISOString(),
        name,
        phone,
        email,
        city,
        qualification,
        mode,
        batch,
        startDate,
        message: fullMessageDetails,
        courseName,
        academyName,
        category,
        duration,
        fee
      };
      const existing = JSON.parse(localStorage.getItem('novaskills_enquiries') || '[]');
      existing.unshift(leadData);
      localStorage.setItem('novaskills_enquiries', JSON.stringify(existing));
      if (formContainer) formContainer.setAttribute('hidden', '');
      if (successContainer) successContainer.removeAttribute('hidden');
    }
  });
  if (!success) {
    showEnrollError('An error occurred submitting your enquiry to Google Sheets. Please try again.');
  }
}
function showEnrollError(msg) {
  const errDiv = document.getElementById('enroll-form-error');
  if (errDiv) {
    errDiv.textContent = msg;
    errDiv.removeAttribute('hidden');
  }
}
function createMobileSlider(trackEl) {
  if (!trackEl || trackEl.dataset.sliderInitialized === 'true') return;
  const cards = Array.from(trackEl.children);
  if (cards.length === 0) return;
  trackEl.dataset.sliderInitialized = 'true';
  trackEl.classList.add('mobile-slider-active');
  const dotsNav = document.createElement('div');
  dotsNav.className = 'mobile-slider-dots';
  cards.forEach((_, idx) => {
    const dot = document.createElement('button');
    dot.className = `mobile-slider-dot ${idx === 0 ? 'active' : ''}`;
    dot.setAttribute('aria-label', `Go to slide ${idx + 1}`);
    dot.addEventListener('click', () => {
      const cardWidth = trackEl.getBoundingClientRect().width + 16;
      trackEl.scrollTo({ left: idx * cardWidth, behavior: 'smooth' });
    });
    dotsNav.appendChild(dot);
  });
  trackEl.parentNode.insertBefore(dotsNav, trackEl.nextSibling);
  let isUserInteracting = false;
  let autoplayTimer = null;
  function updateActiveDot() {
    const scrollPos = trackEl.scrollLeft;
    const cardWidth = trackEl.getBoundingClientRect().width;
    const activeIndex = Math.round(scrollPos / (cardWidth || 1));
    const dots = dotsNav.querySelectorAll('.mobile-slider-dot');
    dots.forEach((dot, i) => {
      dot.classList.toggle('active', i === activeIndex);
    });
  }
  trackEl.addEventListener('scroll', updateActiveDot, { passive: true });
  function startAutoplay() {
    stopAutoplay();
    autoplayTimer = setInterval(() => {
      if (isUserInteracting || window.innerWidth > 768) return;
      const cardWidth = trackEl.getBoundingClientRect().width;
      const activeIndex = Math.round(trackEl.scrollLeft / (cardWidth || 1));
      let nextIndex = activeIndex + 1;
      if (nextIndex >= cards.length) nextIndex = 0;
      trackEl.scrollTo({ left: nextIndex * cardWidth, behavior: 'smooth' });
    }, 5500);
  }
  function stopAutoplay() {
    if (autoplayTimer) {
      clearInterval(autoplayTimer);
      autoplayTimer = null;
    }
  }
  function pauseUserTouch() {
    isUserInteracting = true;
    stopAutoplay();
  }
  function resumeUserTouch() {
    setTimeout(() => {
      isUserInteracting = false;
      startAutoplay();
    }, 4000);
  }
  trackEl.addEventListener('touchstart', pauseUserTouch, { passive: true });
  trackEl.addEventListener('touchend', resumeUserTouch, { passive: true });
  trackEl.addEventListener('mouseenter', pauseUserTouch);
  trackEl.addEventListener('mouseleave', resumeUserTouch);
  startAutoplay();
}
function initAllMobileSliders() {
  if (window.innerWidth <= 768) {
    const mentorsGrid = document.querySelector('.mentors-grid');
    const testimonialsGrid = document.querySelector('.testimonials-grid');
    if (mentorsGrid) createMobileSlider(mentorsGrid);
    if (testimonialsGrid) createMobileSlider(testimonialsGrid);
  }
}
document.addEventListener('DOMContentLoaded', () => {
  injectComponents();
  injectEnrollmentModalHTML();
  requestAnimationFrame(() => {
    initShared();
    initScrollReveal();
    initCounters();
    initAllMobileSliders();
  });
});
window.addEventListener('resize', () => {
  initAllMobileSliders();
});